/**
 * Help pages — per-role user guides.
 *
 * Covers:
 *  - /help redirects each authenticated role to their own guide
 *  - guide route access control (own role + admin; wrong role bounces home)
 *  - the donor guide is public (guests can read it, guests on /help go to login)
 *  - discovery: header Help link and dashboard Help card for signed-in users
 *  - layout: table of contents anchors every section, screenshots load, and
 *    anchor jumps land on the target section
 *
 * Runs in the default (guest) project; roles use the storageState files
 * generated by global-setup, and the donor logs in via the UI (no donor
 * storageState exists).
 */
import { test, expect } from "@playwright/test";

const GUIDE_ROUTES: Record<string, string> = {
  admin: "/help/admin",
  referrer: "/help/referrer",
  family: "/help/family",
  purchaser: "/help/purchaser",
  delivery: "/help/delivery",
  donor: "/help/donor",
};

const DONOR_CREDS = { email: "olivia.reynolds@example.com", password: "Password123!" };

/* Roles that have a storageState file (global-setup); the donor logs in via UI */
const STORAGE_ROLES = ["admin", "referrer", "family", "purchaser", "delivery"] as const;

test.describe("help: routing and access control", () => {
  test("guest /help redirects to login", async ({ browser }) => {
    const context = await browser.newContext();
    const page = await context.newPage();

    await page.goto("/help");
    await expect(page).toHaveURL(/\/login/);

    await context.close();
  });

  test("guest /help/donor is public", async ({ browser }) => {
    const context = await browser.newContext();
    const page = await context.newPage();

    await page.goto("/help/donor");
    await expect(page).toHaveURL("/help/donor");
    await expect(page.getByRole("heading", { name: "Sponsor Guide" })).toBeVisible();

    await context.close();
  });

  test("guests are locked out of the other guides", async ({ browser }) => {
    const context = await browser.newContext();
    const page = await context.newPage();

    for (const role of ["admin", "referrer", "family", "purchaser", "delivery"]) {
      await page.goto(GUIDE_ROUTES[role]);
      await expect(page).toHaveURL(/\/login/);
    }

    await context.close();
  });

  for (const role of STORAGE_ROLES) {
    test(`${role} /help redirects to the ${role} guide`, async ({ browser }) => {
      const context = await browser.newContext({ storageState: `storage/${role}.json` });
      const page = await context.newPage();

      await page.goto("/help");
      await expect(page).toHaveURL(GUIDE_ROUTES[role]);

      await context.close();
    });
  }

  test("donor /help redirects to the donor guide", async ({ browser }) => {
    const context = await browser.newContext();
    const page = await context.newPage();

    await page.goto("/login");
    await page.getByLabel("Email").fill(DONOR_CREDS.email);
    await page.getByLabel("Password").fill(DONOR_CREDS.password);
    await page.getByRole("button", { name: "Sign in" }).click();
    await page.waitForURL(/\/dashboard/);

    await page.goto("/help");
    await expect(page).toHaveURL("/help/donor");

    await context.close();
  });

  test("admin can open every guide", async ({ browser }) => {
    const context = await browser.newContext({ storageState: "storage/admin.json" });
    const page = await context.newPage();

    for (const route of Object.values(GUIDE_ROUTES)) {
      await page.goto(route);
      await expect(page).toHaveURL(route);
    }

    await context.close();
  });

  test("referrer cannot open other roles' guides", async ({ browser }) => {
    const context = await browser.newContext({ storageState: "storage/referrer.json" });
    const page = await context.newPage();

    for (const route of [GUIDE_ROUTES.admin, GUIDE_ROUTES.family, GUIDE_ROUTES.purchaser, GUIDE_ROUTES.delivery]) {
      await page.goto(route);
      await expect(page).toHaveURL(/\/dashboard/);
    }

    await context.close();
  });
});

test.describe("help: discovery and layout", () => {
  test("signed-in header shows a Help link to /help", async ({ browser }) => {
    const context = await browser.newContext({ storageState: "storage/referrer.json" });
    const page = await context.newPage();

    await page.goto("/dashboard");
    /* Scope to the header: the dashboard's Help nav card also matches the
       name "Help", and a page-wide locator would hit a strict-mode violation */
    await expect(page.locator("header").getByRole("link", { name: "Help" })).toHaveAttribute("href", "/help");

    await context.close();
  });

  test("guest header has no Help link", async ({ browser }) => {
    const context = await browser.newContext();
    const page = await context.newPage();

    await page.goto("/home");
    await expect(page.getByRole("link", { name: "Help" })).not.toBeVisible();

    await context.close();
  });

  test("dashboard shows a Help card for a referrer", async ({ browser }) => {
    const context = await browser.newContext({ storageState: "storage/referrer.json" });
    const page = await context.newPage();

    await page.goto("/dashboard");
    const card = page.getByRole("link", { name: /Step-by-step guide for your role/ });
    await expect(card).toHaveAttribute("href", "/help");

    await context.close();
  });

  test("admin guide has a TOC covering its sections and loading screenshots", async ({ browser }) => {
    const context = await browser.newContext({ storageState: "storage/admin.json" });
    const page = await context.newPage();

    await page.goto("/help/admin");
    await expect(page.getByRole("heading", { level: 1, name: "Admin Guide" })).toBeVisible();

    /* TOC links point at section anchors, and each anchor exists in the page */
    const toc = page.getByRole("navigation", { name: "On this page" });
    const tocLinks = toc.getByRole("link");
    const count = await tocLinks.count();
    expect(count).toBeGreaterThan(0);
    for (let i = 0; i < count; i++) {
      const href = await tocLinks.nth(i).getAttribute("href");
      expect(href).toMatch(/^#\w/);
      await expect(page.locator(href as string)).toBeAttached();
    }

    /* Screenshots are Vite-imported assets; verify at least one loads.
       Scroll through first so lazy-loaded (below the fold) images fetch. */
    for (let i = 1; i <= 10; i++) {
      await page.evaluate((f) => window.scrollTo(0, document.documentElement.scrollHeight * f), i / 10);
      await page.waitForTimeout(400);
    }
    const images = page.locator("main img");
    const imgCount = await images.count();
    expect(imgCount).toBeGreaterThan(0);
    /* Wait for every image to finish loading (localhost is fast, but be exact) */
    await expect
      .poll(
        async () =>
          await images.evaluateAll(
            (imgs) =>
              imgs
                .filter((i): i is HTMLImageElement => i instanceof HTMLImageElement)
                .filter((i) => i.complete && i.naturalWidth > 0)
                .length,
          ),
        { timeout: 10_000, message: "all guide screenshots should load" },
      )
      .toBe(imgCount);
    for (let i = 0; i < imgCount; i++) {
      await expect(images.nth(i)).toHaveAttribute("alt", /./);
    }
  });

  test("admin guide TOC anchor jumps land on the target section", async ({ browser }) => {
    const context = await browser.newContext({ storageState: "storage/admin.json" });
    const page = await context.newPage();

    await page.goto("/help/admin");
    await expect(page.getByRole("heading", { level: 1, name: "Admin Guide" })).toBeVisible();

    /* Jump straight from the top to the LAST section: the most screenshots
       sit above it, so unreserved lazy-image space would push it furthest
       from the landing spot (the page grows as images load mid-scroll). */
    await page
      .getByRole("navigation", { name: "On this page" })
      .getByRole("link", { name: "Guides for other roles" })
      .click();

    /* scroll-mt-20 pins the section 80px below the viewport top once settled.
       A large y means the document was still growing while the scroll ran. */
    await expect
      .poll(async () => (await page.locator("#role-guides").boundingBox())?.y, {
        timeout: 10_000,
        message: "the section should land just below the sticky header",
      })
      .toBeLessThan(300);

    await context.close();
  });

  test("admin guide links to every other role guide", async ({ browser }) => {
    const context = await browser.newContext({ storageState: "storage/admin.json" });
    const page = await context.newPage();

    await page.goto("/help/admin");
    await expect(page.getByRole("heading", { level: 1, name: "Admin Guide" })).toBeVisible();
    /* Admins support the other roles: the guide must point at every other guide */
    await expect(page.getByRole("link", { name: "Referrer Guide" })).toHaveAttribute("href", "/help/referrer");
    await expect(page.getByRole("link", { name: "Family Guide" })).toHaveAttribute("href", "/help/family");
    await expect(page.getByRole("link", { name: "Purchaser Guide" })).toHaveAttribute("href", "/help/purchaser");
    await expect(page.getByRole("link", { name: "Delivery Guide" })).toHaveAttribute("href", "/help/delivery");
    /* The site footer (from ProtectedRoute) also links the Sponsor Guide, so scope to the content column */
    await expect(page.locator("main").getByRole("link", { name: "Sponsor Guide" })).toHaveAttribute("href", "/help/donor");

    await context.close();
  });

  test("donor guide renders its own footer with the sponsor guide link", async ({ browser }) => {
    const context = await browser.newContext();
    const page = await context.newPage();

    await page.goto("/help/donor");
    const footer = page.getByRole("contentinfo");
    await expect(footer).toBeVisible();
    await expect(footer.getByRole("link", { name: "Sponsor Guide" })).toHaveAttribute("href", "/help/donor");
    await expect(footer.getByRole("link", { name: "Wish List Guide" })).toHaveAttribute("href", "/wish-list-guide");

    await context.close();
  });

  test("donor guide footer Sponsor Guide, clicked mid-page, scrolls back to the top", async ({ browser }) => {
    const context = await browser.newContext();
    const page = await context.newPage();

    await page.goto("/help/donor");
    const footer = page.getByRole("contentinfo");
    await expect(footer.getByRole("link", { name: "Sponsor Guide" })).toBeVisible({ timeout: 10_000 });

    /* Same page, so the navigation changes nothing: the footer link must
       scroll to the top itself. */
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    await expect.poll(() => page.evaluate(() => window.scrollY)).toBeGreaterThan(100);

    await footer.getByRole("link", { name: "Sponsor Guide" }).click();
    await expect.poll(() => page.evaluate(() => window.scrollY)).toBe(0);

    await context.close();
  });

  test("authenticated guide does not render a duplicate footer", async ({ browser }) => {
    const context = await browser.newContext({ storageState: "storage/admin.json" });
    const page = await context.newPage();

    await page.goto("/help/admin");
    /* Wait for the lazy guide chunk to finish (the route Suspense shows a spinner) */
    await expect(page.getByRole("heading", { level: 1, name: "Admin Guide" })).toBeVisible();
    /* Exactly one footer: the one from ProtectedRoute */
    expect(await page.getByRole("contentinfo").count()).toBe(1);

    await context.close();
  });
});
